export type MRCreateStatus =
  (typeof MRCreateStatus)[keyof typeof MRCreateStatus];

export const MRCreateStatus = {
  active: "active",
  inactive: "inactive",
} as const;

export interface MRCreate {
  /**
   * @minLength 1
   * @maxLength 300
   */
  addressLine1: string;
  /** @maxLength 300 */
  addressLine2?: string;
  /**
   * @minLength 1
   * @maxLength 100
   */
  city: string;
  contactRequirement?: MRCreateContactRequirement;
  /**
   * @minLength 1
   * @maxLength 100
   */
  country: string;
  dateOfJoining: string;
  designation_id: string;
  dialCountry?: MRCreateDialCountry;
  /**
   * @minimum 0
   * @maximum 3650
   */
  doctorDaysLimit?: number;
  /** @maxLength 320 */
  email?: string;
  /**
   * @minLength 1
   * @maxLength 64
   */
  employeeCode: string;
  hq: string;
  initialPassword?: string | null;
  /**
   * @minLength 1
   * @maxLength 200
   */
  landmark: string;
  /**
   * @minLength 1
   * @maxLength 200
   */
  name: string;
  paymentLimit?: number | string;
  /** @maxLength 20 */
  phone?: string;
  /** @pattern ^[1-9][0-9]{5}$ */
  pincode: string;
  reportingManagerId?: string | null;
  reportingStaffId?: string | null;
  /**
   * @minLength 1
   * @maxLength 100
   */
  state: string;
  status: MRCreateStatus;
  userId?: string;
  zoneId: string;
  zoneIds?: string[] | null;
}

