export type MRDirectoryResponseStatus =
  (typeof MRDirectoryResponseStatus)[keyof typeof MRDirectoryResponseStatus];

export const MRDirectoryResponseStatus = {
  active: "active",
  inactive: "inactive",
} as const;

export interface MRDirectoryResponse {
  /**
   * @minLength 1
   * @maxLength 300
   */
  addressLine1: string;
  /** @maxLength 300 */
  addressLine2?: string;
  assignedZones: MRChoice[];
  assignmentWarnings: string[];
  /**
   * @minLength 1
   * @maxLength 100
   */
  city: string;
  contactRequirement?: MRDirectoryResponseContactRequirement;
  /**
   * @minLength 1
   * @maxLength 100
   */
  country: string;
  createdAt: string;
  createdBy: string;
  dateOfJoining: string;
  readonly designationName: string;
  designation_id: string;
  dialCountry?: MRDirectoryResponseDialCountry;
  /**
   * @minimum 0
   * @maximum 3650
   */
  doctorDaysLimit?: number;
  /** @maxLength 320 */
  email?: string;
  /**
   * @minLength 1
   * @maxLength 64
   */
  employeeCode: string;
  hq: string;
  hqName: string;
  id: string;
  /**
   * @minLength 1
   * @maxLength 200
   */
  landmark: string;
  /**
   * @minLength 1
   * @maxLength 200
   */
  name: string;
  /** @pattern ^(?!^[-+.]*$)[+-]?0*(?:\d{0,9}|(?=[\d.]{1,12}0*$)\d{0,9}\.\d{0,2}0*$) */
  paymentLimit?: string;
  /** @maxLength 20 */
  phone?: string;
  /** @pattern ^[1-9][0-9]{5}$ */
  pincode: string;
  reportingManagerId?: string | null;
  reportingManagerName: string;
  reportingStaffId?: string | null;
  reportingStaffName?: string;
  /**
   * @minLength 1
   * @maxLength 100
   */
  state: string;
  status: MRDirectoryResponseStatus;
  updatedAt: string;
  updatedBy: string;
  /**
   * @minLength 3
   * @maxLength 32
   * @pattern ^[a-z][a-z0-9._-]{2,31}$
   */
  userId: string;
  version: number;
  zoneId: string;
  zoneIds: string[];
  zoneName: string;
}

